using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Agents.AI;

var services = new ServiceCollection();

// Load API key from environment variable
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this application.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();

// Create the tools available to the agent
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// Create the research agent using Microsoft Agent Framework
var agent = chatClient.AsAIAgent(
    name: "ResearchAgent",
    description: "An AI research assistant that searches the web and takes notes to produce summaries.",
    instructions: """
        You are a research agent. When given a topic:
        1. Search the web multiple times with different queries to gather diverse information.
        2. Save important findings as notes using the SaveNote tool.
        3. After gathering enough information (at least 3-5 searches), retrieve your notes and produce
           a well-structured summary with key findings, organized by theme.
        4. Always cite which search queries led to which findings.
        Be thorough but concise. Focus on factual, up-to-date information.
        """,
    tools: tools);

// Run the agent
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 50));
Console.WriteLine();

var session = await agent.CreateSessionAsync();
var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

await foreach (var update in agent.RunStreamingAsync(messages, session, options))
{
    Console.Write(update.Text);
}

Console.WriteLine();
Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine("Research complete.");

// --- Tool implementations ---

var notes = new List<string>();

[Description("Searches the web for information on a given query. Returns a summary of search results.")]
static string WebSearch([Description("The search query to look up")] string query)
{
    // Simulated web search results for demonstration purposes.
    // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
    Console.WriteLine($"  🔍 Searching: \"{query}\"");

    return query.ToLowerInvariant() switch
    {
        var q when q.Contains("quantum computing") && q.Contains("2024") =>
            """
            Search results for quantum computing 2024:
            1. IBM unveiled its 1,121-qubit Condor processor and demonstrated error correction breakthroughs.
            2. Google's Willow chip achieved quantum error correction below threshold for the first time.
            3. Microsoft announced a topological qubit milestone bringing fault-tolerant quantum computing closer.
            4. Quantum computing market expected to reach $65 billion by 2030.
            """,
        var q when q.Contains("quantum") && q.Contains("application") =>
            """
            Search results for quantum computing applications:
            1. Drug discovery: simulating molecular interactions for pharmaceutical research.
            2. Cryptography: quantum key distribution for secure communications.
            3. Optimization: solving complex logistics and financial modeling problems.
            4. Machine learning: quantum-enhanced algorithms for pattern recognition.
            5. Climate modeling: simulating complex atmospheric systems.
            """,
        var q when q.Contains("quantum") && q.Contains("challenge") =>
            """
            Search results for quantum computing challenges:
            1. Decoherence: qubits lose quantum state rapidly, requiring near-absolute-zero temperatures.
            2. Error rates: current quantum computers have high error rates needing error correction.
            3. Scalability: connecting many qubits while maintaining coherence remains difficult.
            4. Talent shortage: limited workforce trained in quantum information science.
            5. Cost: quantum hardware requires specialized, expensive infrastructure.
            """,
        var q when q.Contains("ai") && q.Contains("2024") =>
            """
            Search results for AI developments 2024:
            1. OpenAI released GPT-4o with multimodal capabilities across text, vision, and audio.
            2. Google DeepMind's Gemini models achieved state-of-the-art in multiple benchmarks.
            3. Meta released Llama 3 as open-source, accelerating open AI development.
            4. AI regulation advanced with the EU AI Act entering into force.
            5. Agentic AI emerged as a key trend with autonomous task completion.
            """,
        var q when q.Contains("climate") && q.Contains("2024") =>
            """
            Search results for climate change 2024:
            1. 2024 confirmed as hottest year on record, surpassing 1.5°C above pre-industrial levels.
            2. Renewable energy capacity grew 50% globally, led by solar installations.
            3. COP29 in Baku resulted in new climate finance commitments of $300B annually.
            4. Arctic sea ice reached second-lowest extent on record.
            5. Electric vehicle sales exceeded 17 million units worldwide.
            """,
        _ =>
            $"""
            Search results for "{query}":
            1. Multiple sources discuss various aspects of this topic.
            2. Recent developments show growing interest and investment in this area.
            3. Experts predict significant advances in the coming years.
            4. Key challenges include scalability, cost, and public understanding.
            5. Several organizations are actively working on solutions and innovations.
            """
    };
}

[Description("Saves a research note for later reference. Use this to record important findings.")]
string SaveNote(
    [Description("A title or category for the note")] string title,
    [Description("The content of the note")] string content)
{
    var note = $"[{title}]: {content}";
    notes.Add(note);
    Console.WriteLine($"  📝 Note saved: \"{title}\"");
    return $"Note saved successfully: {title}";
}

[Description("Retrieves all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
    {
        return "No notes saved yet.";
    }

    Console.WriteLine($"  📋 Retrieving {notes.Count} notes");
    return string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
}

